import{_ as i,l as s,o as e,c as n,v as o,p as l,x as r,d as E,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"披露理论","description":"","frontmatter":{"title":"披露理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/disclosure-theory.md","filePath":"econ/disclosure-theory.md","lastUpdated":1789023840000}'),p={name:"econ/disclosure-theory.md"};function h(A,a,B,m,u,_){const t=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="披露理论" tabindex="-1">披露理论 <a class="header-anchor" href="#披露理论" aria-label="Permalink to &quot;披露理论&quot;">​</a></h1><div class="epigraph"><p>能被验证的好消息会被说出来；沉默在均衡里被读成坏消息，直到全部揭开——除非披露本身有成本或有接收端的摩擦。</p><footer>—— Grossman, The Informational Role of Warranties and Private Disclosure about Product Quality, Journal of Law and Economics, 1981；Milgrom, Good News and Bad News, Bell Journal, 1981</footer></div><p><a href="/econ/asymmetric-info-liquidity">上一课</a>里信息通过交易泄漏，价差是保险费。本课缺口是<strong>主动开口</strong>：持有可验证信号的人，要不要把它变成 Morris–Shin 意义上的公共 \\(y\\)。不重写报价的贝叶斯，不把披露写成监管清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>卖方（或经理）看见质量或 \\(\\theta\\)，买方只见披露与否。若披露可验证、成本为零，好类型有激励说出自己，以区别于较差类型；买方把沉默解释为「还不够好」，于是次好者也说——逆向归纳把除最差以外全部揭开。Grossman（1981）、Milgrom（1981）的揭开（unraveling）是柠檬市场的对偶：Akerlof 里质量不可验证，坏货驱逐好货；这里可验证，好货驱逐沉默。</p><p>缺口是：为何现实不是完全披露。成本（准备、专有信息泄漏给对手）、接收端不确定（Dye：买方不知道你有没有信号）、或验证只能到区间，都会在中间截断。Verrecchia 把披露成本写成阈值：只有 \\(\\theta\\) 高过阈值才开口，价格对沉默打一个条件期望的折。</p><p><span class="marginnote">与上一课程有限注意力对照：揭开假定接收端读得懂。注意力预算会阻断逆向归纳——沉默不再充分统计「最差」，因为也可能是「没被读到」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>验证披露：消息一旦说出即被相信。均衡是阈值或完全揭开。把披露接到资产定价：公开 \\(y\\) 改变后验，也改变不利选择（知情交易者的信息优势下降，价差可收）。但 Morris–Shin 警告：若定价含协调，多一条公共 \\(y\\) 不必改进福利。本课把两股力并列，不让其中一句吞掉另一句。</p><p>策略性补充：只披露好的可验证部分、把坏的留在交易泄漏里。此时价差与公告并存——公告不是信息的全部通道。GS 采集仍在后台：披露改变的是公共与私有的分界，不是采集成本本身。</p>',10)),(e(),l(d,null,{default:r(()=>[c(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20VER%5B%22%E5%8F%AF%E9%AA%8C%E8%AF%81%E3%80%81%E9%9B%B6%E6%88%90%E6%9C%AC%22%5D%20--%3E%20UNR%5B%22%E6%8F%AD%E5%BC%80%3A%20%E6%B2%89%E9%BB%98%20%3D%20%E6%9C%80%E5%B7%AE%22%5D%0A%20%20COST%5B%22%E6%8A%AB%E9%9C%B2%E6%88%90%E6%9C%AC%22%5D%20--%3E%20THR%5B%22%E9%98%88%E5%80%BC%E6%8A%AB%E9%9C%B2%22%5D%0A%20%20DYE%5B%22%E6%8E%A5%E6%94%B6%E7%AB%AF%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%9C%89%E6%97%A0%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20PART%5B%22%E9%83%A8%E5%88%86%E6%B2%89%E9%BB%98%E4%B8%8D%E6%98%AF%E6%9C%80%E5%B7%AE%22%5D%0A%20%20THR%20--%3E%20Y%5B%22%E5%85%AC%E5%85%B1%20y%22%5D%0A%20%20Y%20--%3E%20SPR%5B%22%E4%B8%8D%E5%88%A9%E9%80%89%E6%8B%A9%E5%8F%AF%E5%8F%98%22%5D%0A%20%20Y%20--%3E%20MS%5B%22%E5%8D%8F%E8%B0%83%E4%B8%8B%E7%A6%8F%E5%88%A9%E4%B8%8D%E5%AE%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>不要把强制披露写成「所以价格更有效」的实证结论。强制把阈值推低，改变的是谁开口；有效仍相对信息集，且联合着 <a href="/econ/stochastic-discount-factor">SDF</a> 的风险调整。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>揭开的机制是信念的逆向归纳，与信号博弈的直觉准则同族：好类型有便宜的分离动作（说出可验证的好），沉默无法被好类型使用。成本破坏便宜：中等类型觉得开口的专有成本高于分离收益，池定在沉默。买方理性地给沉默一个截断分布的均值，不是给零。</p><p>与柠檬的关系：不可验证时开口无用，市场靠价格推测平均质量，可以关闭。可验证时开口太有用，市场几乎不让你闭嘴。中间地带——半可验证、有成本、有注意力——才是工作理论。</p><p><span class="marginnote">Jovanovic、Verrecchia 的自愿披露，Dye 的「投资者不知道经理有没有消息」，是截断而不是否定揭开。强制披露的理论价值，是在这些摩擦上移动阈值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写会计准则条文，不估计公告窗口。下一课把开口外包：评级、分析师、审计，作为生产 \\(y\\) 的中介。企业自己的阈值与中介的激励是两套委托。</p><p>也不要把披露当成限价簿上的「展示冰山」。展示是协议选择；披露是关于 \\(\\theta\\) 的可验证陈述。切点仍在 <a href="/econ/to-limit-order-book">到限价簿</a>。</p><p>后课默认：可验证零成本则揭开；成本与接收摩擦给出阈值。公共 \\(y\\) 改变不利选择，福利还要过 Morris–Shin 那一关。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可验证、零成本：逆向归纳揭开，沉默等于最差。</li><li>成本或「不知有无信号」截断披露，沉默对应一个条件期望。</li><li>公告与交易泄漏是两条通道，不是互斥。</li><li>出处：Grossman, <em>JLE</em> 1981；Milgrom, <em>Bell</em> 1981；Verrecchia；Dye。</li></ul>',11))])}const T=i(p,[["render",h]]);export{D as __pageData,T as default};
